(function(root){
 'use strict';
 const football=()=>root.Football||(typeof require==='function'?require('./engine.js'):null),own='brynwell',opponent=g=>g.home===own?g.away:g.home;
 const points=rows=>rows.reduce((n,g)=>n+(g.score[0]>g.score[1]?3:g.score[0]===g.score[1]?1:0),0);
 const complete=g=>g.statisticsOriginMinute===0&&(!g.unassignedGoals||Number.isInteger(g.continuousVersion)&&g.continuousVersion>=1&&g.continuousVersion<=14&&Array.isArray(g.ownGoals)&&g.ownGoals.length===g.unassignedGoals&&g.unassignedGoals<=g.score[0]);
 function timeline(s){return [...(s.statistics?.archive||[]).flatMap(a=>a.records),...(s.statistics?.records||[])];}
 function read(s,q){
  if(!q)return null;const F=football(),all=timeline(s),index=all.findIndex(g=>g.id===q.id),before=q.phase==='before',record=!before&&index>=0&&complete(all[index])&&JSON.stringify(all[index].score)===JSON.stringify(q.score)?all[index]:null,source=(index>=0?all.slice(0,index+(before?0:1)):before?all.filter(g=>g.year<=q.year):[]),prefix=source.filter(complete),current=prefix.filter(g=>g.year===q.year),leagueWindow=source.filter(g=>g.year===q.year&&g.competition==='league').slice(-3),recent=leagueWindow.filter(complete),h2h=(before?prefix:prefix.filter(g=>g.id!==q.id)).filter(g=>opponent(g)===opponent(q)).at(-1);
  let topic='first',fact='아직 확정한 공식 경기가 없습니다.',question='“이름값보다 오늘 준비한 걸 보여주겠다는 뜻인가요?”',brief=q.opponent+'전. 이름보다 준비로 답할 건가요?',thought='첫 질문부터 정답은 없다. 준비한 만큼만 말하자.',reaction='기자는 미래의 성적 대신 다음에 확인할 준비를 적었다.';
  const choose=(id,proof,ask,short,inner,echo)=>{topic=id;fact=proof;question=ask;brief=short;thought=inner;reaction=echo;};
  if(before){
   if(q.competition!=='league')choose('knockout',q.competition==='cup'?'국내컵 · 이번 대회 경기 전':'유럽 대회 · 이번 대회 경기 전','“리그와는 다른 무대죠. 결과를 서두르다가 준비한 기준까지 버리진 않을 겁니까?”',q.opponent+'전. 다른 대회에서도 같은 기준인가요?','리그 순위가 이 경기의 득점을 대신해주진 않는다. 지금 상대부터 보자.','기자는 대회의 이름과 감독이 말한 준비의 기준을 나란히 적었다.');
   else if(recent.length===3&&recent.every(g=>g.score[0]>g.score[1]))choose('winning-run','최근 확정 리그 3경기 · 3승 · 9점','“리그 세 경기를 연달아 이겼습니다. 좋은 흐름이라는 말이 방심이 되진 않을까요?”',q.opponent+'전. 리그 3연승, 방심은 없나요?','잘될 때 한 말이 제일 크게 돌아온다. 선수들 대신 들뜨지 말자.','기자는 3연승 기록 옆에, 아직 치르지 않은 경기는 별개라는 감독의 답을 메모했다.');
   else if(recent.length===3&&recent.every(g=>g.score[0]<g.score[1]))choose('losing-run','최근 확정 리그 3경기 · 3패 · 0점','“리그 세 경기를 연달아 졌습니다. 같은 말을 반복하기보다, 달라질 근거가 있습니까?”',q.opponent+'전. 리그 3연패, 달라질 근거는요?','또 준비하겠다는 말로 끝내면 아무도 안 믿겠지. 내가 실제로 고른 것부터 설명하자.','기자는 세 번의 패배를 지우지 않고, 다음 준비를 보겠다는 답을 그 아래 남겼다.');
   else if(h2h)choose('meeting-again','지난 맞대결 · '+h2h.year+'시즌 '+h2h.round+'R · '+h2h.score.join(' : '),'“지난 맞대결은 우리 팀 기준 '+h2h.score.join(' : ')+'였습니다. 그때와 같은 장면이 나오면 어떻게 받아들이실 겁니까?”',q.opponent+'와 다시 만납니다. 지난 경기 기억하나요?','기억하는 것과 다시 막아내는 건 다른 일이다. 지난 점수로 오늘을 설명하진 말자.','기자는 지난 맞대결의 점수를 적고, 이번 결과를 먼저 단정하는 문장은 지웠다.');
   else if(recent.length)choose('recent-form','최근 확정 리그 '+recent.length+'경기 · 승점 '+points(recent)+'점','“최근 리그 '+recent.length+'경기에서 '+points(recent)+'점을 얻었습니다. 지금 흐름을 결과 한 줄로만 설명할 수 있을까요?”',q.opponent+'전. 최근 리그 '+points(recent)+'점, 다음 준비는요?','기자는 점수를 묻지만 선수들은 내가 누구를 고르는지 볼 거다. 두 질문을 따로 피하진 말자.','기자는 확정된 승점과 아직 남은 준비를 나누어 받아 적었다.');
   else if(leagueWindow.length)choose('limited-records','이번 시즌 리그 결과 · 전체 경기의 세부 기록 확인 필요','“확인한 장면만으로 팀 전체를 단정할 수는 없겠죠. 다음 명단은 어떤 기준으로 정합니까?”',q.opponent+'전. 확인한 결과와 다음 명단의 기준은요?','아는 장면과 모르는 장면을 섞어 말하지 말자. 숫자를 채우는 것보다 내가 확인한 준비를 말하는 게 먼저다.','기자는 확인하지 못한 세부 평가를 비워 두었다. 감독의 다음 준비를 보겠다는 질문은 남겼다.');
   else if(current.length)choose('first-league','이번 시즌 확정 공식 경기 '+current.length+'경기 · 이번 시즌 리그 결과 대기','“다른 대회에서 얻은 경험을 이번 리그 준비에 어떻게 가져오실 겁니까?”',q.opponent+'전. 이번 리그에서 보여줄 준비는요?','다른 무대의 점수까지 오늘의 승점인 것처럼 말하진 말자.','기자는 대회 결과와 리그 승점이 다르다는 점을 확인했다.');
   else if(prefix.length)choose('season-opening',q.year+'시즌 · 새 리그 성적은 첫 경기부터','“새 시즌입니다. 지난 성적을 내려놓고, 첫 명단으로 어떤 기준을 보여주실 건가요?”',q.opponent+'전. 새 시즌, 첫 명단의 기준은요?','이번엔 다르다는 말은 쉽다. 지난 말보다 오늘의 명단이 먼저 보이겠지. 처음 맡은 날의 기준도 잊지 말자.','기자는 지난 시즌 성적표를 덮고 새 페이지를 폈다. 감독의 답 옆, 이번 시즌 첫 결과가 들어갈 자리는 아직 비어 있었다.');
  }else if(record){
   const score=q.score.join(' : '),win=q.score[0]>q.score[1],draw=q.score[0]===q.score[1],cards=(record.cards||[]).filter(c=>c.card==='red'),sub=record.players.filter(p=>p.minutes>0&&!p.started&&p.goals>0).sort((a,b)=>b.goals-a.goals||a.identity.localeCompare(b.identity))[0],star=record.players.filter(p=>p.goals>=2).sort((a,b)=>b.goals-a.goals||a.identity.localeCompare(b.identity))[0],keeper=record.players.find(p=>p.cleanSheets>0);
   if(q.penalties)choose('penalties','정규·연장 점수 '+score+' · 승부차기 '+q.penalties.join(' : '),'“승부차기에서는 한 사람의 장면이 크게 남습니다. 오늘 결과를 특정 선수의 이름으로만 설명할 건 아니죠?”','승부차기 '+q.penalties.join(' : ')+'. 누구에게 책임을 묻나요?','마지막 킥 한 번으로 여기까지 온 시간을 지우지 말자.','기자는 경기 점수와 승부차기 점수를 구분하고, 감독의 책임에 대한 답을 남겼다.');
   else if(cards.length)choose('dismissal','확정 점수 '+score+' · 우리 퇴장 '+cards.filter(c=>c.team===0).length+'명 / 상대 퇴장 '+cards.filter(c=>c.team===1).length+'명','“퇴장이 있었던 경기입니다. 숫자가 바뀐 뒤 내린 선택도 감독의 판단이었죠?”',score+'. 퇴장 뒤 선택은 설명할 수 있나요?','카드 한 장으로 모든 설명을 끝내면 편하지. 그 뒤에 내가 한 선택까지 없어지는 건 아니다.','기자는 퇴장 시각 옆에 그다음 선택을 적었다. 카드 한 장에 가려졌던 감독의 결정이 다시 질문으로 돌아왔다.');
   else if((record.ownGoals?.length||0)+(record.opponentOwnGoals?.length||0)>0)choose('own-goal','확정 점수 '+score+' · 상대 자책골로 얻은 득점 '+(record.ownGoals?.length||0)+' / 우리 자책골로 내준 실점 '+(record.opponentOwnGoals?.length||0),record.opponentOwnGoals?.length?'“우리 팀의 자책골도 있었습니다. 한 장면의 책임으로 선수의 경기를 전부 설명하진 않을 거죠?”':'“상대 자책골도 우리 득점에 포함됐습니다. 결과의 운과 준비한 과정을 어떻게 나누어 보십니까?”',score+'. 자책골이 있던 경기, 한 장면만 보실 건가요?','굴절된 공 한 번이 한 사람의 이름을 덮어서는 안 된다. 그 전후에 우리가 한 선택도 보자.','기자는 자책골을 일반 득점자의 골과 구분해 적었다. 한 장면만 남기지 않겠다는 답도 그 옆에 붙었다.');
   else if(sub){const name=F.identityProfile(sub.identity)?.name||'교체 선수';choose('bench-scorer','확정 점수 '+score+' · '+name+' 후보 출전 '+sub.minutes+'분 · '+sub.goals+'골','“'+name+' 선수가 후보로 들어가 '+sub.goals+'골을 넣었습니다. 교체가 적중했다는 평가, 선수의 준비와 어떻게 나누실 겁니까?”',score+'. 후보 '+name+'의 골, 누구의 준비였나요?','내 교체가 맞았다고 말하기 전에, 불릴 때까지 준비한 시간을 먼저 보자.','기자는 교체 명단의 작은 이름에 밑줄을 그었다. 이름이 불리기 전에도 준비는 계속됐다는 말이 노트에 남았다.');}
   else if(star){const name=F.identityProfile(star.identity)?.name||'득점 선수';choose('multiple-goals','확정 점수 '+score+' · '+name+' '+star.goals+'골','“'+name+' 선수가 '+star.goals+'골을 넣었습니다. 한 사람에게 더 큰 기대가 몰릴 텐데요?”',score+'. '+name+' '+star.goals+'골, 커진 기대는요?','오늘의 골을 다음 경기의 의무로 만들지는 말자. 좋은 날을 보낸 사람도 다시 준비해야 한다.','오늘의 골을 다음 경기의 의무로 만들지는 않겠다는 답이 인터뷰 노트 끝에 남았다.');}
   else if(keeper){const name=F.identityProfile(keeper.identity)?.name||'골키퍼';choose('clean-sheet','확정 점수 '+score+' · '+name+' '+keeper.minutes+'분 · 무실점','“무실점입니다. 골키퍼의 공과 앞에서 막아준 동료들의 공을 함께 설명해 주실 수 있을까요?”',score+'. 무실점, 골문 앞 동료들도 보셨나요?','막은 사람은 골키퍼지만, 그 앞에서 뛰어준 사람들의 이름도 잊지 말자.','기자는 골키퍼의 이름 옆에 수비 전체의 준비라고 적었다. 기사는 골문 앞 한 사람에게서 끝나지 않았다.');}
   else choose(win?'win':draw?'draw':'loss','확정 경기 '+score+' · 우리 '+q.score[0]+'득점 / '+q.score[1]+'실점',win?'“이겼습니다. 좋은 결과 뒤에도 다음 준비에서 고칠 부분은 직접 말할 수 있겠습니까?”':draw?'“승점을 나눴습니다. 얻은 것과 놓친 것을 같은 말로 설명하진 않으시겠죠?”':'“졌습니다. 선수들에게 요구한 것과 감독이 준비한 것, 어느 쪽부터 돌아보실 겁니까?”',score+'. '+(win?'이긴 뒤에도 고칠 부분은요?':draw?'얻은 점과 놓친 점은요?':'다음 준비, 누가 먼저 바뀌나요?'),win?'오늘은 웃을 수 있다. 그렇다고 모든 선택이 정답이었다고 적진 말자.':'점수는 이미 정해졌다. 여기서 누군가를 작게 만들어 내 책임을 줄이진 말자.','결과표 옆에 감독이 남긴 말이 함께 실렸다. 다음 경기의 명단은 그 답을 다시 평가할 근거가 될 것이다.');
  }else if(!before)choose('confirmed-result','확정 점수 '+(q.score||[]).join(' : '),'“확인되지 않은 개인 기록보다, 확정된 결과와 준비한 선택부터 설명해 주세요.”',(q.score||[]).join(' : ')+'. 결과를 어떻게 설명할 건가요?','모르는 기록을 아는 것처럼 말하지 말자. 내가 확인한 선택부터 답하자.','기자는 확정 점수만 남기고, 확인할 수 없는 개인 기록의 평가는 보류했다.');
  return {topic,fact,question,brief,thought,reaction,source:record?.id||null};
 }
 function paragraphs(s,style){
  const g=s.statistics?.records?.at(-1);if(!g)return ['구단의 이름과 과거 명성만으로는 아직 오늘의 경기력을 평가할 수 없다. 첫 명단과 첫 경기가 새로운 판단의 출발점이다.'];
  if(!complete(g))return ['최근 경기의 세부 기록은 경기 전체를 담고 있지 않다. 일부 장면의 개인 기록을 전체 경기 평가로 넓혀 해석하지 않고, 확정 점수와 확인된 준비를 구분해 살펴본다.'];
  const leagueWindow=(s.statistics?.records||[]).filter(r=>r.year===g.year&&r.competition==='league').slice(-3),rows=leagueWindow.filter(complete),scope=rows.length===leagueWindow.length?'이번 시즌 최근 확정 리그 '+rows.length+'경기':'최근 리그 '+leagueWindow.length+'경기 중 전체 기록을 확인한 '+rows.length+'경기',score=g.score.join(' : '),F=football(),base=rows.length?scope+'의 승점은 '+points(rows)+'점이다. 컵 경기와 아직 확정하지 않은 경기는 이 승점에 포함하지 않았다.':leagueWindow.length?'최근 리그 '+leagueWindow.length+'경기의 세부 기록은 전체 경기 평가에 쓰지 않았다. 다른 대회 결과를 리그 승점으로 합산하지 않았다.':'아직 이번 시즌에 확정된 리그 경기는 없다. 다른 대회 결과를 리그 승점으로 합산하지 않았다.';
  if(style==='players'){const list=g.players.filter(p=>p.minutes>0).slice().sort((a,b)=>(b.goals*4+b.assists*2+b.cleanSheets)-(a.goals*4+a.assists*2+a.cleanSheets)||b.minutes-a.minutes||a.identity.localeCompare(b.identity)).slice(0,3);return [list.map(p=>(F.identityProfile(p.identity)?.name||'선수')+' '+p.minutes+'분 · '+p.goals+'골 · '+p.assists+'도움'+(p.cleanSheets?' · 무실점':'')).join('. ')+'. 득점과 도움은 눈에 띄는 기여다. 동료를 위해 비운 공간과 돌아온 수비처럼 숫자 바깥의 장면도 선수 평가에서 함께 볼 대목이다.',base];}
  if(style==='analysis'){const starts=g.players.filter(p=>p.started).length,subs=g.players.filter(p=>!p.started&&p.minutes>0).length,reds=(g.cards||[]).filter(c=>c.team===0&&c.card==='red').length;return ['최근 경기 '+score+'에서 선발 출전은 '+starts+'명, 후보로 투입된 선수는 '+subs+'명이다. '+(reds?'우리 팀의 실제 퇴장 '+reds+'명도 이 경기의 조건이었다. ':'')+'결과가 좋았다는 이유만으로 모든 교체가 정답이었다고, 결과가 나빴다는 이유만으로 모든 준비가 틀렸다고 단정할 수는 없다.',base];}
  return [base,'경기 뒤의 점수와 다음 명단 사이에는 선수들이 기다리는 시간이 있다. 감독의 말을 평가할 다음 근거도 새 결과와 실제 출전 기록이어야 한다. 아직 뛰지 않은 경기의 승리나 영입 효과를 미리 성과로 적지는 않는다.'];
 }
 const api={read,paragraphs};root.PressContext=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
